import sys
sys.setrecursionlimit(200000)
def solve(n, arr, queries):
    size = 1
    while size < n: size <<= 1
    tree = [0] * (2 * size); lazy = [0] * (2 * size)
    for i in range(n): tree[size + i] = arr[i]
    for i in range(size - 1, 0, -1): tree[i] = tree[2*i] + tree[2*i+1]
    def push_down(node, ns):
        if lazy[node]:
            cs = ns // 2
            tree[2*node] += lazy[node] * cs; lazy[2*node] += lazy[node]
            tree[2*node+1] += lazy[node] * cs; lazy[2*node+1] += lazy[node]
            lazy[node] = 0
    def update(l, r, val, node=1, nl=0, nr=None):
        if nr is None: nr = size - 1
        if r < nl or nr < l: return
        if l <= nl and nr <= r: tree[node] += val*(nr-nl+1); lazy[node] += val; return
        push_down(node, nr-nl+1); mid = (nl+nr)//2
        update(l,r,val,2*node,nl,mid); update(l,r,val,2*node+1,mid+1,nr)
        tree[node] = tree[2*node] + tree[2*node+1]
    def query(l, r, node=1, nl=0, nr=None):
        if nr is None: nr = size - 1
        if r < nl or nr < l: return 0
        if l <= nl and nr <= r: return tree[node]
        push_down(node, nr-nl+1); mid = (nl+nr)//2
        return query(l,r,2*node,nl,mid) + query(l,r,2*node+1,mid+1,nr)
    out = []
    for type_, l, r, *rest in queries:
        if type_ == 1: update(l, r, rest[0])
        else: out.append(str(query(l, r)))
    return "\n".join(out)

if __name__ == '__main__':
    data = sys.stdin.read().split()
    idx = 0
    n = int(data[idx]); idx += 1
    arr = list(map(int, data[idx:idx+n])); idx += n
    q = int(data[idx]); idx += 1
    queries = []
    for _ in range(q):
        t = int(data[idx]); l = int(data[idx+1]); r = int(data[idx+2]); idx += 3
        if t == 1: v = int(data[idx]); idx += 1; queries.append((t,l,r,v))
        else: queries.append((t,l,r))
    print(solve(n, arr, queries))

